CREATE TABLE IF NOT EXISTS public.reporter_identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone_hash text NOT NULL UNIQUE, phone_masked text NOT NULL, verified_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.spotter_reporter_links (spotter_id uuid PRIMARY KEY, reporter_id uuid NOT NULL REFERENCES public.reporter_identities(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.phone_verification_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), spotter_id uuid NOT NULL, phone_hash text NOT NULL, event_type text NOT NULL CHECK (event_type IN ('send','check')), provider_status text NOT NULL DEFAULT 'requested', created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.sightings ADD COLUMN IF NOT EXISTS reporter_id uuid REFERENCES public.reporter_identities(id) ON DELETE SET NULL;
ALTER TABLE public.sightings ADD COLUMN IF NOT EXISTS gps_accuracy_m double precision;
CREATE INDEX IF NOT EXISTS sightings_reporter_time_idx ON public.sightings(reporter_id,created_at DESC);
CREATE TABLE IF NOT EXISTS public.eta_calibration_samples (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL REFERENCES public.trips(id) ON DELETE CASCADE, route_id text NOT NULL REFERENCES public.routes(id), from_checkpoint_id uuid NOT NULL REFERENCES public.checkpoints(id), to_checkpoint_id uuid NOT NULL REFERENCES public.checkpoints(id), bus_type text NOT NULL CHECK (bus_type IN ('ordinary','aircon')), baseline_minutes numeric(8,2) NOT NULL, observed_minutes numeric(8,2) NOT NULL, reporter_count integer NOT NULL, mean_gps_accuracy_m numeric(8,2) NOT NULL, quality_score numeric(5,2) NOT NULL, observed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (trip_id,to_checkpoint_id));
CREATE INDEX IF NOT EXISTS eta_calibration_samples_segment_idx ON public.eta_calibration_samples(route_id,from_checkpoint_id,to_checkpoint_id,bus_type,created_at DESC);
CREATE TABLE IF NOT EXISTS public.eta_segment_calibrations (route_id text NOT NULL REFERENCES public.routes(id), from_checkpoint_id uuid NOT NULL REFERENCES public.checkpoints(id), to_checkpoint_id uuid NOT NULL REFERENCES public.checkpoints(id), bus_type text NOT NULL CHECK (bus_type IN ('ordinary','aircon')), sample_count integer NOT NULL, median_minutes numeric(8,2) NOT NULL, p80_minutes numeric(8,2) NOT NULL, baseline_minutes numeric(8,2) NOT NULL, last_sample_at timestamptz NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (route_id,from_checkpoint_id,to_checkpoint_id,bus_type));
CREATE TABLE IF NOT EXISTS public.report_quality_daily (metric_date date PRIMARY KEY, report_count integer NOT NULL DEFAULT 0, verified_report_count integer NOT NULL DEFAULT 0, otp_verified_report_count integer NOT NULL DEFAULT 0, unique_verified_reporters integer NOT NULL DEFAULT 0, median_gps_accuracy_m numeric(8,2), median_report_distance_m numeric(8,2), calibration_sample_count integer NOT NULL DEFAULT 0, calibrated_segment_count integer NOT NULL DEFAULT 0, average_quality_score numeric(5,2), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.ops_health_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), status text NOT NULL CHECK (status IN ('healthy','degraded','unavailable')), database_latency_ms integer NOT NULL, active_trip_count integer NOT NULL, stale_active_trip_count integer NOT NULL, calibration_segment_count integer NOT NULL, latest_sighting_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.ops_alerts (alert_key text PRIMARY KEY, severity text NOT NULL CHECK (severity IN ('info','warning','critical')), message text NOT NULL, first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE INDEX IF NOT EXISTS phone_verification_events_session_idx ON public.phone_verification_events(spotter_id,event_type,created_at DESC);
CREATE INDEX IF NOT EXISTS phone_verification_events_phone_idx ON public.phone_verification_events(phone_hash,event_type,created_at DESC);
CREATE INDEX IF NOT EXISTS ops_health_snapshots_created_idx ON public.ops_health_snapshots(created_at DESC);
CREATE INDEX IF NOT EXISTS report_quality_daily_date_idx ON public.report_quality_daily(metric_date DESC);
